// Return RC low-pass filter output samples, given input samples,
// time interval dt, and time constant RC
function lowpass(real[1..n] x, real dt, real RC)
    var real[1..n] y
    var real α := dt / (RC + dt)
    y[1] := α * x[1]
    for i from 2 to n
        y[i] := α * x[i] + (1 - α) * y[i - 1]
    return y
